import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    s = data.lstrip('-')
    cnt = [0] * 10
    for ch in s:
        cnt[ord(ch) - 48] += 1
    for d in range(10):
        if cnt[d]:
            print(d, cnt[d])

if __name__ == "__main__":
    main()
